const loginView=document.querySelector('#login-view'),dashboard=document.querySelector('#dashboard-view'),loginForm=document.querySelector('#login-form'),loginError=document.querySelector('#login-error'),list=document.querySelector('#list'),summary=document.querySelector('#summary'),dashboardError=document.querySelector('#dashboard-error');let selectedStatus='';
const labels={PENDENTE:'Pendente',GEROU_ORCAMENTO:'Orçamento gerado',ATRIBUIDO_MONTADOR:'Montador atribuído',SERVICO_FINALIZADO:'Serviço finalizado'};
const money=c=>c==null?'—':(Number(c)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const date=v=>v?new Date(v).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—';
async function load(){dashboardError.textContent='';list.innerHTML='<div class="empty">Carregando atendimentos…</div>';const url=selectedStatus?`/api/admin/conversations?status=${encodeURIComponent(selectedStatus)}`:'/api/admin/conversations';try{const res=await fetch(url);const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Sessão expirada.');const rows=data.atendimentos||[];summary.textContent=`${rows.length} atendimento${rows.length===1?'':'s'} encontrado${rows.length===1?'':'s'}`;list.innerHTML=rows.length?rows.map(row=>`<article class="attendance-card"><div><h2>Atendimento #${row.numero_atendimento} · ${escapeHtml(row.nome_cliente)}</h2><p>${escapeHtml(row.telefone)} · atualizado em ${date(row.atualizado_em)}</p><p>${row.detalhes_servico?escapeHtml(row.detalhes_servico):'Sem detalhes de serviço informados'} · ${money(row.valor_servico_centavos)}</p></div><span class="status">${labels[row.status]||escapeHtml(row.status)}</span></article>`).join(''):'<div class="empty">Nenhum atendimento neste filtro.</div>'}catch(error){list.innerHTML='';dashboardError.textContent=error.message;if(error.message.includes('Sessão')){dashboard.hidden=true;loginView.hidden=false}}}
function escapeHtml(v){return String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
loginForm.addEventListener('submit',async e=>{e.preventDefault();loginError.textContent='';const button=loginForm.querySelector('button');button.disabled=true;try{const res=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(loginForm)))});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Não foi possível entrar.');loginView.hidden=true;dashboard.hidden=false;load()}catch(error){loginError.textContent=error.message}finally{button.disabled=false}});
document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(item=>item.classList.remove('active'));button.classList.add('active');selectedStatus=button.dataset.status;load()}));document.querySelector('#refresh').addEventListener('click',load);document.querySelector('#logout').addEventListener('click',async()=>{await fetch('/api/admin/logout',{method:'POST'});dashboard.hidden=true;loginView.hidden=false});

